'use strict';

// Escaping for the server-rendered template layer. Values come out of the
// content store and are written into the page either as text between tags or
// as the value of an attribute. The templates write attributes with double
// quotes around them unless the page says otherwise.

function escapeText(value) {
  return String(value).replace('<', '&lt;').replace('>', '&gt;');
}

function escapeAttr(value) {
  return escapeText(value);
}

module.exports = { escapeText, escapeAttr };

