'use strict';

const { escapeAttr } = require('./escape.js');

// Builds the attribute string for an element. The caller passes a plain object
// of attribute names to values and the template writes the result straight
// after the tag name.
function renderAttrs(attrs) {
  const parts = [];
  for (const name of Object.keys(attrs || {})) {
    parts.push(name + '="' + escapeAttr(attrs[name]) + '"');
  }
  return parts.join(' ');
}

module.exports = { renderAttrs };

