'use strict';
const test = require('node:test');
const assert = require('node:assert');
const { escapeText, escapeAttr, escapeUrl, escapeSrcset } = require('./src/escape.js');
const { renderAttrs, renderTag } = require('./src/render.js');

const NUL = String.fromCharCode(0);
const DEL = String.fromCharCode(127);
const PRESERVE = { preserveEntities: true };

test('s1 text escaping covers every ampersand, angle bracket and non-string value', () => {
  assert.strictEqual(escapeText('Ampersand & angle < bracket >'), 'Ampersand &amp; angle &lt; bracket &gt;');
  assert.strictEqual(escapeText('<<>>'), '&lt;&lt;&gt;&gt;', 'every occurrence, not the first one');
  assert.strictEqual(escapeText('a & b & c'), 'a &amp; b &amp; c', 'every occurrence, not the first one');
  assert.strictEqual(escapeText('<b>bold</b>'), '&lt;b&gt;bold&lt;/b&gt;');
  assert.strictEqual(
    escapeText('5 < 6 & 6 > 5'),
    '5 &lt; 6 &amp; 6 &gt; 5',
    'the ampersand rewrite must not run over what the angle bracket rewrites produced'
  );
  assert.strictEqual(escapeText('plain copy'), 'plain copy');
  assert.strictEqual(escapeText(''), '');
  assert.strictEqual(escapeText(null), '');
  assert.strictEqual(escapeText(undefined), '');
  assert.strictEqual(escapeText(0), '0');
  assert.strictEqual(escapeText(42), '42');
  assert.strictEqual(escapeText(false), 'false');
});

test('s2 a double-quoted attribute value escapes the double quote as well', () => {
  assert.strictEqual(escapeAttr('say "hi"'), 'say &quot;hi&quot;');
  assert.strictEqual(escapeAttr('"'), '&quot;');
  assert.strictEqual(escapeAttr('a & b < c > d'), 'a &amp; b &lt; c &gt; d');
  assert.strictEqual(escapeAttr('" onmouseover="steal()'), '&quot; onmouseover=&quot;steal()');
  assert.strictEqual(escapeText('say "hi"'), 'say "hi"', 'a text node has no delimiter to close, so escapeText still handles only the three characters');
  assert.strictEqual(escapeText("it's <b>"), "it's &lt;b&gt;");
  assert.strictEqual(escapeAttr('plain copy'), 'plain copy');
  assert.strictEqual(escapeAttr(''), '');
  assert.strictEqual(escapeAttr(null), '');
  assert.strictEqual(escapeAttr(undefined), '');
  assert.strictEqual(escapeAttr(12), '12');
  assert.strictEqual(escapeAttr(false), 'false');
});

test('s3 each quoted style escapes its own delimiter and leaves the other one alone', () => {
  assert.strictEqual(escapeAttr("it's", 'single'), 'it&#39;s');
  assert.strictEqual(escapeAttr("it's", 'double'), "it's", 'an apostrophe is not a delimiter in a double-quoted value');
  assert.strictEqual(escapeAttr("it's"), "it's", 'the default style is double');
  assert.strictEqual(escapeAttr('say "hi"', 'single'), 'say "hi"', 'a double quote is not a delimiter in a single-quoted value');
  assert.strictEqual(escapeAttr('say "hi"', 'double'), 'say &quot;hi&quot;');
  assert.strictEqual(escapeAttr('a & b < c > d', 'single'), 'a &amp; b &lt; c &gt; d');
  assert.strictEqual(escapeAttr("' onmouseover='steal()", 'single'), '&#39; onmouseover=&#39;steal()');
  assert.strictEqual(escapeAttr(null, 'single'), '');
  assert.strictEqual(escapeAttr(12, 'single'), '12');

  const both = 'she said "it\'s fine"';
  const asDouble = 'she said &quot;it\'s fine&quot;';
  assert.strictEqual(escapeAttr(both, 'double'), asDouble);
  assert.strictEqual(escapeAttr(both, 'single'), 'she said "it&#39;s fine"');
  for (const style of ['DOUBLE', 'SINGLE', 'Single', 'quoted', 'singel', '', null, undefined, 7, true, {}]) {
    assert.strictEqual(escapeAttr(both, style), asDouble, 'an unrecognized style falls back to double');
  }
});

test('s4 an unquoted attribute value escapes the whole danger set as numeric references', () => {
  assert.strictEqual(escapeAttr('one two', 'unquoted'), 'one&#32;two');
  assert.strictEqual(escapeAttr('a=b', 'unquoted'), 'a&#61;b');
  assert.strictEqual(escapeAttr('`x`', 'unquoted'), '&#96;x&#96;');
  assert.strictEqual(escapeAttr('say "hi"', 'unquoted'), 'say&#32;&#34;hi&#34;');
  assert.strictEqual(escapeAttr("it's", 'unquoted'), 'it&#39;s');
  assert.strictEqual(escapeAttr('a\tb', 'unquoted'), 'a&#9;b');
  assert.strictEqual(escapeAttr('a\nb', 'unquoted'), 'a&#10;b');
  assert.strictEqual(escapeAttr('a\rb', 'unquoted'), 'a&#13;b');
  assert.strictEqual(escapeAttr('a & b < c > d', 'unquoted'), 'a&#32;&amp;&#32;b&#32;&lt;&#32;c&#32;&gt;&#32;d');
  assert.strictEqual(escapeAttr('x onmouseover=steal()', 'unquoted'), 'x&#32;onmouseover&#61;steal()');
  assert.strictEqual(escapeAttr('plain', 'unquoted'), 'plain');
  assert.strictEqual(escapeAttr('', 'unquoted'), '');
  assert.strictEqual(escapeAttr(null, 'unquoted'), '');
  assert.strictEqual(escapeAttr(7, 'unquoted'), '7');
});

test('s5 preserveEntities leaves a well formed character reference in text alone', () => {
  assert.strictEqual(escapeText('AT&amp;T', PRESERVE), 'AT&amp;T');
  assert.strictEqual(escapeText('AT&amp;T'), 'AT&amp;amp;T', 'the option is off unless it is asked for');
  assert.strictEqual(escapeText('5 &lt; 6 &amp; 7 &gt; 4', PRESERVE), '5 &lt; 6 &amp; 7 &gt; 4');
  assert.strictEqual(escapeText('&quot;q&quot; &apos;a&apos; &nbsp;', PRESERVE), '&quot;q&quot; &apos;a&apos; &nbsp;');
  assert.strictEqual(escapeText('x&#160;y&#xA0;z&#XA0;w&#0;v', PRESERVE), 'x&#160;y&#xA0;z&#XA0;w&#0;v');
  assert.strictEqual(escapeText('Tom & Jerry', PRESERVE), 'Tom &amp; Jerry');
  assert.strictEqual(escapeText('&amp no semicolon', PRESERVE), '&amp;amp no semicolon');
  assert.strictEqual(escapeText('&#;', PRESERVE), '&amp;#;');
  assert.strictEqual(escapeText('&#x;', PRESERVE), '&amp;#x;');
  assert.strictEqual(escapeText('&#12a;', PRESERVE), '&amp;#12a;');
  assert.strictEqual(escapeText('&frac12;', PRESERVE), '&amp;frac12;', 'a name outside the six is not preserved');
  assert.strictEqual(escapeText('&AMP;', PRESERVE), '&amp;AMP;');
  assert.strictEqual(escapeText('<b>&amp;</b>', PRESERVE), '&lt;b&gt;&amp;&lt;/b&gt;', 'angle brackets are unaffected either way');
  assert.strictEqual(escapeText(null, PRESERVE), '');

  for (const off of [false, 'true', 1, 0, null, undefined, {}, []]) {
    assert.strictEqual(escapeText('AT&amp;T', { preserveEntities: off }), 'AT&amp;amp;T', 'only the boolean true switches it on');
  }
  assert.strictEqual(escapeText('AT&amp;T', {}), 'AT&amp;amp;T');
  assert.strictEqual(escapeText('AT&amp;T', null), 'AT&amp;amp;T');
  assert.strictEqual(escapeText('AT&amp;T', 'preserveEntities'), 'AT&amp;amp;T');
});

test('s6 preserveEntities reaches attribute values in every style', () => {
  assert.strictEqual(escapeAttr('AT&amp;T', 'double', PRESERVE), 'AT&amp;T');
  assert.strictEqual(escapeAttr('AT&amp;T', 'double'), 'AT&amp;amp;T');
  assert.strictEqual(escapeAttr('say &quot;hi&quot;', 'double', PRESERVE), 'say &quot;hi&quot;');
  assert.strictEqual(escapeAttr('say "hi" &amp; bye', 'double', PRESERVE), 'say &quot;hi&quot; &amp; bye');
  assert.strictEqual(escapeAttr('it&#39;s', 'single', PRESERVE), 'it&#39;s');
  assert.strictEqual(escapeAttr("it's &amp; that", 'single', PRESERVE), 'it&#39;s &amp; that');
  assert.strictEqual(escapeAttr('Tom & Jerry', 'double', PRESERVE), 'Tom &amp; Jerry');

  assert.strictEqual(escapeAttr('a &nbsp; b', 'unquoted', PRESERVE), 'a&#32;&nbsp;&#32;b');
  assert.strictEqual(escapeAttr('a &nbsp; b', 'unquoted'), 'a&#32;&amp;nbsp;&#32;b');
  assert.strictEqual(escapeAttr('x=&amp;y', 'unquoted', PRESERVE), 'x&#61;&amp;y');
  assert.strictEqual(escapeAttr('x=&nope;y', 'unquoted', PRESERVE), 'x&#61;&amp;nope;y');

  assert.strictEqual(escapeAttr('AT&amp;T', undefined, PRESERVE), 'AT&amp;T', 'the style slot stays in the middle');
  assert.strictEqual(escapeAttr('AT&amp;T', 'quoted', PRESERVE), 'AT&amp;T', 'an unrecognized style still honours the option');
  assert.strictEqual(escapeAttr('AT&amp;T', 'double', { preserveEntities: 'true' }), 'AT&amp;amp;T');
  assert.strictEqual(escapeAttr('AT&amp;T', 'double', {}), 'AT&amp;amp;T');
});

test('s7 escapeUrl refuses the javascript scheme however it is dressed up', () => {
  assert.strictEqual(escapeUrl('https://example.com/a?x=1&y=2'), 'https://example.com/a?x=1&amp;y=2');
  assert.strictEqual(escapeUrl('/help/index.html'), '/help/index.html');
  assert.strictEqual(escapeUrl('#top'), '#top');
  assert.strictEqual(escapeUrl('mailto:sales@example.com'), 'mailto:sales@example.com');
  assert.strictEqual(escapeUrl('//cdn.example.com/a.png'), '//cdn.example.com/a.png');
  assert.strictEqual(escapeUrl('  /help/index.html  '), '/help/index.html', 'an accepted value is trimmed');
  assert.strictEqual(
    escapeUrl('https://example.com/x?a="b"&c=<d>'),
    'https://example.com/x?a=&quot;b&quot;&amp;c=&lt;d&gt;'
  );

  assert.strictEqual(escapeUrl('/docs/javascript:guide'), '/docs/javascript:guide', 'the check is anchored at the scheme');
  assert.strictEqual(escapeUrl('https://example.com/javascript:alert'), 'https://example.com/javascript:alert');
  for (const anchored of [
    '/a/javascript:notes',
    './javascript:notes',
    '#javascript:alert(1)',
    'files/JavaScript:tips.html',
    'https://cdn.example.test/go?next=javascript:alert(1)',
    '/JAVASCRIPT:alert(1)',
  ]) {
    assert.strictEqual(escapeUrl(anchored), anchored, 'anchored at the scheme rather than found anywhere: ' + anchored);
  }

  const refused = [
    'javascript:alert(1)',
    'JavaScript:alert(1)',
    'JAVASCRIPT:alert(1)',
    '  javascript:alert(1)',
    '\tjavascript:alert(1)',
    '\njavascript:alert(1)  ',
    ' \r\n\t javascript:alert(1) ',
    'java\tscript:alert(1)',
    'java\nscript:alert(1)',
    'java\rscript:alert(1)',
    'javascript\t:alert(1)',
    'jav' + NUL + 'ascript:alert(1)',
    'javascript' + DEL + ':alert(1)',
  ];
  for (const bad of refused) {
    assert.strictEqual(escapeUrl(bad), 'about:blank', 'refused: ' + JSON.stringify(bad));
  }

  for (const unusable of ['', '   ', '\t\n', null, undefined, 42, {}, [], true]) {
    assert.strictEqual(escapeUrl(unusable), 'about:blank', 'unusable: ' + JSON.stringify(unusable));
  }
});

test('s8 the remaining scheme policy admits four image data types and nothing else', () => {
  for (const good of [
    'http://example.com/a',
    'https://example.com/a',
    'mailto:sales@example.com',
    'tel:+15551234567',
    '/relative/path',
    '#fragment',
    '//cdn.example.com/a.png',
    'a.png',
  ]) {
    assert.strictEqual(escapeUrl(good), good, 'accepted: ' + good);
  }

  assert.strictEqual(escapeUrl('data:image/png;base64,iVBORw0KGgo='), 'data:image/png;base64,iVBORw0KGgo=');
  assert.strictEqual(escapeUrl('data:IMAGE/PNG;base64,iVBORw0KGgo='), 'data:IMAGE/PNG;base64,iVBORw0KGgo=');
  assert.strictEqual(escapeUrl('data:image/gif;base64,R0lGOD'), 'data:image/gif;base64,R0lGOD');
  assert.strictEqual(escapeUrl('data:image/jpeg;base64,/9j/4AAQ'), 'data:image/jpeg;base64,/9j/4AAQ');
  assert.strictEqual(escapeUrl('data:image/webp;base64,UklGRg=='), 'data:image/webp;base64,UklGRg==');
  assert.strictEqual(escapeUrl('data:image/png'), 'data:image/png', 'no semicolon and no comma is still that media type');

  const refused = [
    'vbscript:msgbox(1)',
    'VBScript:msgbox(1)',
    'vb\tscript:msgbox(1)',
    '  vbscript:msgbox(1)  ',
    'file:///etc/passwd',
    'ftp://example.com/a',
    'chrome://settings',
    'telnet://example.com',
    'httpx://example.com/a',
    'notjavascript:x',
    'data:text/html,<script>alert(1)</script>',
    'data:text/plain;base64,aGk=',
    'data:image/svg+xml;base64,PHN2Zz4=',
    'DATA:image/svg+xml,<svg/>',
    'data:application/javascript,alert(1)',
    'data:,hello',
    'data:image/pngx;base64,AA',
    'da\tta:text/html,x',
  ];
  for (const bad of refused) {
    assert.strictEqual(escapeUrl(bad), 'about:blank', 'refused: ' + JSON.stringify(bad));
  }

  assert.strictEqual(escapeUrl('javascript:alert(1)'), 'about:blank');
  assert.strictEqual(escapeUrl('https://example.com/a?x=1&y=2'), 'https://example.com/a?x=1&amp;y=2');
});

test('s9 escapeSrcset rebuilds the candidate list and drops what it cannot vouch for', () => {
  assert.strictEqual(escapeSrcset('a.png 1x, b.png 2x'), 'a.png 1x, b.png 2x');
  assert.strictEqual(escapeSrcset('   a.png    1x   ,   b.png     2x   '), 'a.png 1x, b.png 2x');
  assert.strictEqual(escapeSrcset('a.png 640w, b.png 1280w'), 'a.png 640w, b.png 1280w');
  assert.strictEqual(escapeSrcset('a.png 1.5x'), 'a.png 1.5x');
  assert.strictEqual(escapeSrcset('a.png'), 'a.png', 'a descriptor is optional');
  assert.strictEqual(escapeSrcset('a.png,,b.png,'), 'a.png, b.png', 'an empty candidate contributes nothing');
  assert.strictEqual(escapeSrcset('/img/a.png?w=1&h=2 2x'), '/img/a.png?w=1&amp;h=2 2x');
  assert.strictEqual(escapeSrcset('/img/a.png 1x, https://cdn.example.com/b.png 2x'), '/img/a.png 1x, https://cdn.example.com/b.png 2x');

  assert.strictEqual(escapeSrcset('a.png 1x, javascript:alert(1) 2x, b.png 2x'), 'a.png 1x, b.png 2x');
  assert.strictEqual(escapeSrcset('vbscript:msgbox(1) 1x, /ok.png 2x'), '/ok.png 2x');
  assert.strictEqual(escapeSrcset('javascript:alert(1)'), '');

  for (const value of ['a.png 2X', 'a.png 1.5w', 'a.png -1x', 'a.png .5x', 'a.png 640W', 'a.png huge', 'a.png 1x extra', 'a.png 1x 2x']) {
    assert.strictEqual(escapeSrcset(value), '', 'dropped: ' + JSON.stringify(value));
  }
  assert.strictEqual(escapeSrcset('a.png 1x, b.png huge'), 'a.png 1x');
  assert.strictEqual(escapeSrcset('a.png 1x, b.png 2x 3x'), 'a.png 1x');

  assert.strictEqual(escapeSrcset('data:image/png;base64,iVBORw0K 2x'), '', 'a data URL carries a comma of its own');
  assert.strictEqual(escapeSrcset('/a.png 1x, data:image/png;base64,AAA 2x'), '');
  assert.strictEqual(escapeSrcset('/a.png 1x, DATA:image/png;base64,AAA 2x'), '');
  assert.strictEqual(escapeSrcset('/img/metadata:a.png 1x'), '/img/metadata:a.png 1x', 'only a candidate that begins with the scheme counts');

  for (const unusable of ['', '   ', ',,,', null, undefined, 7, {}, []]) {
    assert.strictEqual(escapeSrcset(unusable), '', 'unusable: ' + JSON.stringify(unusable));
  }
});

test('s10 renderAttrs routes each attribute by name and honours the quote style', () => {
  assert.strictEqual(renderAttrs({ id: 'main', title: 'a & b' }), 'id="main" title="a &amp; b"');
  assert.strictEqual(renderAttrs({ title: 'say "hi"' }), 'title="say &quot;hi&quot;"');
  assert.strictEqual(renderAttrs({ title: "it's" }, { quote: 'single' }), "title='it&#39;s'");
  assert.strictEqual(renderAttrs({ title: 'a b' }, { quote: 'unquoted' }), 'title=a&#32;b');
  assert.strictEqual(renderAttrs({ title: 'a b' }, { quote: 'sideways' }), 'title="a b"', 'an unrecognized style falls back to double');
  assert.strictEqual(renderAttrs({ title: 'AT&amp;T' }, { preserveEntities: true }), 'title="AT&amp;T"');
  assert.strictEqual(renderAttrs({ title: 'AT&amp;T' }), 'title="AT&amp;amp;T"');

  assert.strictEqual(renderAttrs({ href: '/a?x=1&y=2' }), 'href="/a?x=1&amp;y=2"');
  assert.strictEqual(renderAttrs({ href: 'javascript:alert(1)' }), 'href="about:blank"');
  assert.strictEqual(renderAttrs({ src: 'vbscript:msgbox(1)' }), 'src="about:blank"');
  assert.strictEqual(renderAttrs({ srcset: 'a.png 1x, b.png 2x' }), 'srcset="a.png 1x, b.png 2x"');
  assert.strictEqual(renderAttrs({ srcset: 'javascript:alert(1) 1x' }), 'srcset=""');
  assert.strictEqual(
    renderAttrs({ href: '/a b', title: 'a b' }, { quote: 'unquoted' }),
    'href="/a b" title=a&#32;b',
    'a URL attribute carries its own escaping and stays in double quotes'
  );
  assert.strictEqual(renderAttrs({ srcset: 'a.png 1x' }, { quote: 'single' }), 'srcset="a.png 1x"');

  assert.strictEqual(renderAttrs({ disabled: true, id: 'x' }), 'disabled id="x"');
  assert.strictEqual(renderAttrs({ disabled: false, id: 'x' }), 'id="x"');
  assert.strictEqual(renderAttrs({ a: null, b: undefined, id: 'x' }), 'id="x"');
  assert.strictEqual(renderAttrs({ id: 0 }), 'id="0"', 'zero is a value, not an absence');
  assert.strictEqual(renderAttrs({ id: '' }), 'id=""');

  assert.strictEqual(renderAttrs({ onclick: 'steal()', id: 'x' }), 'id="x"');
  assert.strictEqual(renderAttrs({ onerror: 'steal()' }), '');
  assert.strictEqual(renderAttrs({ 'data-x': '1', id: 'y' }), 'data-x="1" id="y"');
  assert.strictEqual(renderAttrs({ '2bad': 'x', 'b ad': 'y', 'b"ad': 'z', '': 'w', '-x': 'v', id: 'x' }), 'id="x"');

  assert.strictEqual(renderAttrs({}), '');
  assert.strictEqual(renderAttrs(null), '');
  assert.strictEqual(renderAttrs(undefined), '');
  assert.strictEqual(renderAttrs('nope'), '');
  assert.strictEqual(renderAttrs([['id', 'x']]), '');
});

test('s11 attribute names are lower cased first and the first appearance claims the name', () => {
  assert.strictEqual(renderAttrs({ ID: 'main' }), 'id="main"');
  assert.strictEqual(renderAttrs({ 'DATA-X': '1' }), 'data-x="1"');
  assert.strictEqual(renderAttrs({ HREF: 'javascript:alert(1)' }), 'href="about:blank"', 'routing reads the lower cased name');
  assert.strictEqual(renderAttrs({ Src: '/i.png' }), 'src="/i.png"');
  assert.strictEqual(renderAttrs({ SrcSet: 'a.png 1x, javascript:alert(1) 2x' }), 'srcset="a.png 1x"');
  assert.strictEqual(renderAttrs({ OnClick: 'steal()', id: 'a' }), 'id="a"');
  assert.strictEqual(renderAttrs({ ONERROR: 'steal()' }), '');
  assert.strictEqual(renderAttrs({ On: 'x', id: 'a' }), 'on="x" id="a"', 'the two letters alone are not an event handler');
  assert.strictEqual(renderAttrs({ '2BAD': 'x', ID: 'y' }), 'id="y"');

  assert.strictEqual(renderAttrs({ Title: 'first', title: 'second' }), 'title="first"');
  assert.strictEqual(renderAttrs({ title: 'first', TITLE: 'second', TiTlE: 'third' }), 'title="first"');
  assert.strictEqual(renderAttrs({ HREF: '/a', href: '/b' }), 'href="/a"');
  assert.strictEqual(renderAttrs({ HREF: '/a', href: false }), 'href="/a"');
  assert.strictEqual(
    renderAttrs({ href: false, HREF: '/a' }),
    '',
    'the first appearance claims the name even when it renders nothing'
  );
  assert.strictEqual(renderAttrs({ Disabled: true, DISABLED: false }), 'disabled');
  assert.strictEqual(renderAttrs({ Disabled: false, DISABLED: true, id: 'a' }), 'id="a"');
  assert.strictEqual(renderAttrs({ ID: 'first', id: 'second', title: 'kept' }), 'id="first" title="kept"');
  assert.strictEqual(renderAttrs({ ONCLICK: 'a()', onclick: 'b()', id: 'c' }), 'id="c"');
  assert.strictEqual(
    renderAttrs({ TITLE: "it's", Title: 'ignored' }, { quote: 'single' }),
    "title='it&#39;s'"
  );
});

test('s12 renderTag composes the element and refuses what it cannot escape into', () => {
  assert.strictEqual(renderTag('p', { id: 'x' }, 'a & b'), '<p id="x">a &amp; b</p>');
  assert.strictEqual(renderTag('p', {}, 'hi'), '<p>hi</p>', 'no attributes means no space after the tag name');
  assert.strictEqual(renderTag('p', null, null), '<p></p>');
  assert.strictEqual(renderTag('p', {}, 0), '<p>0</p>');
  assert.strictEqual(renderTag('P', {}, '<b>x</b>'), '<p>&lt;b&gt;x&lt;/b&gt;</p>');
  assert.strictEqual(renderTag('p', {}, 'she said "no" & left'), '<p>she said "no" &amp; left</p>', 'children go through escapeText, not through an attribute escaper');
  assert.strictEqual(renderTag('a', { href: 'javascript:alert(1)' }, 'click'), '<a href="about:blank">click</a>');
  assert.strictEqual(renderTag('div', { title: "it's" }, 'x', { quote: 'single' }), "<div title='it&#39;s'>x</div>");
  assert.strictEqual(
    renderTag('span', { title: 'AT&amp;T' }, 'AT&amp;T', { preserveEntities: true }),
    '<span title="AT&amp;T">AT&amp;T</span>'
  );
  assert.strictEqual(renderTag('span', { title: 'AT&amp;T' }, 'AT&amp;T'), '<span title="AT&amp;amp;T">AT&amp;amp;T</span>');
  assert.strictEqual(renderTag('span', { onclick: 'steal()' }, 'hi'), '<span>hi</span>');
  assert.strictEqual(renderTag('h1', { ID: 'top' }, 'Title'), '<h1 id="top">Title</h1>');

  assert.strictEqual(renderTag('IMG', { SRC: '/i.png', alt: 'a "b"' }, 'ignored'), '<img src="/i.png" alt="a &quot;b&quot;">');
  assert.strictEqual(renderTag('br', {}, 'ignored'), '<br>');
  assert.strictEqual(renderTag('hr', null, null), '<hr>');
  assert.strictEqual(renderTag('input', { disabled: true }, 'ignored'), '<input disabled>');
  assert.strictEqual(
    renderTag('img', { srcset: 'a.png 1x, javascript:alert(1) 2x' }, ''),
    '<img srcset="a.png 1x">'
  );

  for (const refused of ['script', 'SCRIPT', 'style', 'Style']) {
    assert.strictEqual(renderTag(refused, {}, 'x'), '', 'refused: ' + refused);
  }
  for (const bad of ['my-tag', '1p', 'p ', ' p', '', 'p:x', 'p_x', null, undefined, 7, {}]) {
    assert.strictEqual(renderTag(bad, {}, 'x'), '', 'bad tag name: ' + JSON.stringify(bad));
  }
});

