'use strict';

// Escaping for the server-rendered template layer. Values come out of the
// content store and are written into the page either as text between tags or
// as the value of an attribute. The templates write attributes with double
// quotes around them unless the page says otherwise.

const TEXT_MAP = { '&': '&amp;', '<': '&lt;', '>': '&gt;' };

// One map per attribute delimiter. Only the delimiter actually in use has to
// go; the other quote character is not a delimiter in that context.
const STYLE_MAPS = {
  double: { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' },
  single: { '&': '&amp;', '<': '&lt;', '>': '&gt;', "'": '&#39;' },
  unquoted: {
    '&': '&amp;',
    '<': '&lt;',
    '>': '&gt;',
    '"': '&#34;',
    "'": '&#39;',
    '`': '&#96;',
    '=': '&#61;',
    ' ': '&#32;',
    '\t': '&#9;',
    '\n': '&#10;',
    '\r': '&#13;',
  },
};

// A character reference is decoded after the attribute value has been
// delimited, so a numeric reference is safe in an unquoted value where the
// raw character would end or extend it.
const REFERENCE = /^&(?:amp|lt|gt|quot|apos|nbsp);|^&#[0-9]+;|^&#[xX][0-9a-fA-F]+;/;

const SAFE_IMAGE_TYPES = ['image/png', 'image/gif', 'image/jpeg', 'image/webp'];
const ALLOWED_SCHEMES = ['http', 'https', 'mailto', 'tel'];
const REFUSED_URL = 'about:blank';

function preservesEntities(options) {
  return Boolean(options) && typeof options === 'object' && options.preserveEntities === true;
}

function referenceAt(text, index) {
  const found = REFERENCE.exec(text.slice(index));
  return found ? found[0] : null;
}

function escapeWith(map, value, options) {
  if (value === null || value === undefined) return '';
  const text = String(value);
  const preserve = preservesEntities(options);
  let out = '';
  for (let i = 0; i < text.length; i += 1) {
    const ch = text[i];
    if (ch === '&' && preserve) {
      const reference = referenceAt(text, i);
      if (reference !== null) {
        out += reference;
        i += reference.length - 1;
        continue;
      }
    }
    out += Object.prototype.hasOwnProperty.call(map, ch) ? map[ch] : ch;
  }
  return out;
}

function styleMap(style) {
  if (style === 'single' || style === 'unquoted') return STYLE_MAPS[style];
  return STYLE_MAPS.double;
}

function escapeText(value, options) {
  return escapeWith(TEXT_MAP, value, options);
}

function escapeAttr(value, style, options) {
  return escapeWith(styleMap(style), value, options);
}

// The URL parser discards C0 controls and DEL before it reads the scheme, so
// the scheme check has to read the same string the parser will.
function schemeProbe(text) {
  let out = '';
  for (let i = 0; i < text.length; i += 1) {
    const code = text.charCodeAt(i);
    if (code > 31 && code !== 127) out += text[i];
  }
  return out;
}

function dataMediaType(rest) {
  const cut = rest.search(/[;,]/);
  return (cut === -1 ? rest : rest.slice(0, cut)).toLowerCase();
}

function escapeUrl(value) {
  if (typeof value !== 'string') return REFUSED_URL;
  const trimmed = value.trim();
  if (trimmed === '') return REFUSED_URL;
  const probe = schemeProbe(trimmed);
  const found = /^([A-Za-z][A-Za-z0-9+.-]*):/.exec(probe);
  if (found !== null) {
    const scheme = found[1].toLowerCase();
    if (scheme === 'data') {
      if (!SAFE_IMAGE_TYPES.includes(dataMediaType(probe.slice(found[0].length)))) {
        return REFUSED_URL;
      }
    } else if (!ALLOWED_SCHEMES.includes(scheme)) {
      return REFUSED_URL;
    }
  }
