}

function usableDescriptor(descriptor) {
  return /^[0-9]+w$/.test(descriptor) || /^[0-9]+(?:\.[0-9]+)?x$/.test(descriptor);
}

function escapeSrcset(value) {
  if (typeof value !== 'string') return '';
  const kept = [];
  for (const piece of value.split(',')) {
    const candidate = piece.trim();
    if (candidate === '') continue;
    const parts = candidate.split(/\s+/);
    // Splitting on commas cannot put a data URL back together, so one of them
    // anywhere refuses the whole value rather than emitting a broken half.
    if (/^data:/i.test(parts[0])) return '';
    if (parts.length > 2) continue;
    const url = escapeUrl(parts[0]);
    if (url === REFUSED_URL) continue;
    if (parts.length === 1) {
      kept.push(url);
      continue;
    }
    if (!usableDescriptor(parts[1])) continue;
    kept.push(url + ' ' + parts[1]);
  }
  return kept.join(', ');
}

module.exports = { escapeText, escapeAttr, escapeUrl, escapeSrcset };

