'use strict';

const { escapeText, escapeAttr, escapeUrl, escapeSrcset } = require('./escape.js');

const NAME_PATTERN = /^[A-Za-z][A-Za-z0-9-]*$/;
const TAG_PATTERN = /^[a-z][a-z0-9]*$/;
const RAW_TEXT_ELEMENTS = ['script', 'style'];
const VOID_ELEMENTS = [
  'area', 'base', 'br', 'col', 'embed', 'hr', 'img',
  'input', 'link', 'meta', 'source', 'track', 'wbr',
];

function quoteStyle(options) {
  const style = options && typeof options === 'object' ? options.quote : undefined;
  return style === 'single' || style === 'unquoted' ? style : 'double';
}

function delimiterFor(style) {
  if (style === 'single') return "'";
  if (style === 'unquoted') return '';
  return '"';
}

// Builds the attribute string for an element. The caller passes a plain object
// of attribute names to values and the template writes the result straight
// after the tag name.
function renderAttrs(attrs, options) {
  if (!attrs || typeof attrs !== 'object' || Array.isArray(attrs)) return '';
  const style = quoteStyle(options);
  const delimiter = delimiterFor(style);
  const claimed = [];
  const parts = [];
  for (const rawName of Object.keys(attrs)) {
    if (!NAME_PATTERN.test(rawName)) continue;
    const name = rawName.toLowerCase();
    if (name.length > 2 && name.slice(0, 2) === 'on') continue;
    if (claimed.includes(name)) continue;
    claimed.push(name);
    const value = attrs[rawName];
    if (value === false || value === null || value === undefined) continue;
    if (value === true) {
      parts.push(name);
      continue;
    }
    // href, src and srcset carry their own escaping, so they are written in
    // double quotes whatever style the ordinary attributes are using.
    if (name === 'href' || name === 'src') {
      parts.push(name + '="' + escapeUrl(value) + '"');
    } else if (name === 'srcset') {
      parts.push(name + '="' + escapeSrcset(value) + '"');
    } else {
      parts.push(name + '=' + delimiter + escapeAttr(value, style, options) + delimiter);
    }
  }
  return parts.join(' ');
}

function renderTag(name, attrs, children, options) {
  if (typeof name !== 'string') return '';
  const tag = name.toLowerCase();
  if (!TAG_PATTERN.test(tag)) return '';
  // Character references are not decoded inside raw text elements, so there is
  // no safe escaping into them from here.
  if (RAW_TEXT_ELEMENTS.includes(tag)) return '';
  const rendered = renderAttrs(attrs, options);
  const open = '<' + tag + (rendered === '' ? '' : ' ' + rendered) + '>';
  if (VOID_ELEMENTS.includes(tag)) return open;
  return open + escapeText(children, options) + '</' + tag + '>';
}

module.exports = { renderAttrs, renderTag };
